CREATE TABLE `authorization_decisions` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NULL,`team_id` CHAR(36) CHARACTER SET ascii NULL,`capability` VARCHAR(80) CHARACTER SET ascii NOT NULL,`surface` ENUM('api','worker','export','file','event','sse') NOT NULL,`outcome` ENUM('allowed','denied') NOT NULL,`reason` VARCHAR(64) CHARACTER SET ascii NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`occurred_at` DATETIME(3) NOT NULL,`schema_version` SMALLINT UNSIGNED NOT NULL,PRIMARY KEY(`id`),KEY `idx_authz_actor_time`(`actor_id`,`occurred_at`),KEY `idx_authz_org_outcome_time`(`organization_id`,`outcome`,`occurred_at`),KEY `idx_authz_trace`(`trace_id`),CONSTRAINT `fk_authz_actor` FOREIGN KEY(`actor_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
